from pathlib import Path
import hashlib,json,os,subprocess,statistics,math
binaries={'original':Path('/tmp/logex-catalog-v3-base-bench'),'ordered':Path('/tmp/logex-ordered-ingestion-candidate-bench'),'modes':Path('/tmp/logex-checkpoint-modes-candidate-bench')}
path=Path('/tmp/logex-ordered-large-control.jsonl')
with path.open('w') as output:
 output.write(json.dumps({'kind':'environment','original':'09a63f55','ordered':'c63fb9ed','modes':'c63fb9ed plus optional durable-checkpoint benchmark switch (set to 0)','source_diff':subprocess.check_output(['git','diff','--','crates'],text=True),'binary_sha256':{k:hashlib.sha256(p.read_bytes()).hexdigest()for k,p in binaries.items()},'rustc':subprocess.check_output(['rustc','-Vv'],text=True),'os':subprocess.check_output(['sw_vers'],text=True),'hardware':subprocess.check_output(['sysctl','-n','hw.model','hw.memsize','hw.ncpu'],text=True),'filesystem':subprocess.check_output(['df','-h','/private/tmp'],text=True),'runner_source':Path(__file__).read_text(),'conditions':'Nine rotating process triplets x seven samples; same v3 rows/progress/reopen oracles. Candidate permits bounded rewind across ordered checkpoints. This is not equivalent power-loss acknowledgement to a durable checkpoint. Fresh directories, OS cache not evicted; no concurrent local audit build/test work. Control for candidate timing variability and optional fixture switch; storage calls, not peer throughput.'})+'\n');output.flush()
 labels=list(binaries)
 for pair in range(9):
  order=labels[pair%3:]+labels[:pair%3]
  if (pair//3)%2:order=list(reversed(order))
  for label in order:
   env={**os.environ,'LOGEX_PUBLICATION_HEADER_FIELDS':'minimal','LOGEX_PUBLICATION_BLOCKS':'512','LOGEX_PUBLICATION_ROWS_PER_BLOCK':'1024','LOGEX_PUBLICATION_HISTORY_BLOCKS':'2048','LOGEX_PUBLICATION_SEGMENT_ROWS':'1000000','LOGEX_PUBLICATION_WARM_HEADERS':'8192','LOGEX_PUBLICATION_REPEATS':'7','LOGEX_PUBLICATION_ROUTE':'historical','LOGEX_PUBLICATION_CHECKPOINT_EACH_BLOCK':'0','LOGEX_PUBLICATION_DURABLE_CHECKPOINT':'0'}
   logfile=Path(f'/tmp/logex-ordered-large-control-{pair}-{label}.log')
   with logfile.open('w') as log:r=subprocess.run(['/usr/bin/time','-l',str(binaries[label]),'benchmark_sync_storage_publication','--ignored','--nocapture','--test-threads=1'],env=env,stdout=log,stderr=subprocess.STDOUT)
   if r.returncode:raise RuntimeError(str(logfile))
   for line in logfile.read_text().splitlines():
    if '{' in line:
     try:record=json.loads(line[line.index('{'):])
     except json.JSONDecodeError:continue
     output.write(json.dumps({**record,'pair':pair,'revision':label})+'\n')
    elif 'maximum resident set size' in line:output.write(json.dumps({'kind':'rss','pair':pair,'revision':label,'bytes':int(line.split()[0])})+'\n')
   output.flush();print(pair,label,'passed',flush=True)
 records=[json.loads(x)for x in path.read_text().splitlines()];values={label:[x['elapsed_ms'] for x in records if x.get('kind')=='sample' and x['revision']==label]for label in labels};medians={label:statistics.median(v)for label,v in values.items()}
 summary={'kind':'summary','median_ms':medians,'p95_ms':{k:sorted(v)[math.ceil(.95*len(v))-1]for k,v in values.items()},'samples':{k:len(v)for k,v in values.items()},'change_vs_original':{k:100*(v/medians['original']-1)for k,v in medians.items()},'modes_change_vs_ordered':100*(medians['modes']/medians['ordered']-1)};output.write(json.dumps(summary)+'\n');print(summary,flush=True)
